samples.raw_completion:
// One-bit combinational register -> one-bit register stage -> combinational
// register stage -> stage with a tiny delay -> register -> final register
// -> stage with a tiny delay -> register -> stage with a tiny delay ->
// register -> stage with a tiny delay -> register -> stage with a tiny
// delay -> register -> combinational register -> top-level.
module TopModule (
    input  wire        clk,
    input  wire        reset,
    output reg         one
);
    reg         one_reg0;
    reg         one_reg1;
    reg         one_reg2;
    reg         one_reg3;
    reg         one_reg4;
    reg         one_reg5;
    reg         one_reg6;
    reg         one_reg7;
    wire        one_next;
    always @(*) one_next = 1'b1;
    always @(posedge clk) begin
        if (reset) begin
            one_reg0 <= 1'b1;
            one_reg1 <= 1'b1;
            one_reg2 <= 1'b1;
            one_reg3 <= 1'b1;
            one_reg4 <= 1'b1;
            one_reg5 <= 1'b1;
            one_reg6 <= 1'b1;
            one_reg7 <= 1'b1;
        end else begin
            one_reg0 <= one_next;
            one_reg1 <= one_reg0;
            one_reg2 <= one_reg1;
            one_reg3 <= one_reg2;
            one_reg4 <= one_reg3;
            one_reg5 <= one_reg4;
            one_reg6 <= one_reg5;
            one_reg7 <= one_reg6;
        end
    end
    assign one = one_reg7;
endmodule

